#!/bin/sh
# Merge driver for plugins/**/CLAUDE.md.
# Files mix hand-written prose with an <!-- AUTOGENERATED:BEGIN --> block.
# args: %O %A %B %P %S %X %Y  (ancestor, current, other, path, and their labels)
#
# Strategy: the two halves of the file merge differently, so a benign conflict
# cannot occur and a real one is reported to git like any other.
#   - The autogen block is emptied on all three sides before merging (only its
#     BEGIN / END lines stay, as anchors), so it can never conflict; the current
#     side's block is put back afterwards, and the normalize pass (marker below)
#     regenerates it from the merged sources.
#   - The prose is an ordinary 3-way merge. Its exit status IS the driver's: a
#     prose conflict exits non-zero, so git marks the path conflicted (UU) and
#     stops the rebase on it, with readable ours/base/theirs labels. A driver
#     that exited 0 here made git stage the markers as a clean merge, which is
#     how conflicted CLAUDE.md files used to slip through `rebase --continue`.
# `findClaudeMdConflicts` (normalize and the `generated-artifacts-normalized`
# check) remains the backstop for markers that reach a commit anyway.
BEGIN_PREFIX='<!-- AUTOGENERATED:BEGIN'
END_LINE='<!-- AUTOGENERATED:END -->'

# Resolve the marker dir exactly as regen-generated.sh does — read its comment
# there for why the ambient GIT_* pointers are unset first and why an
# unresolvable git dir is fatal instead of a skipped marker.
GITDIR=$(unset GIT_DIR GIT_WORK_TREE GIT_INDEX_FILE GIT_OBJECT_DIRECTORY; git rev-parse --absolute-git-dir 2>/dev/null) ||
  GITDIR=$(git rev-parse --absolute-git-dir 2>/dev/null) || GITDIR=""
if [ -z "$GITDIR" ]; then
  echo "regen-claudemd merge driver: cannot resolve this checkout's git dir; refusing to merge without recording the normalize marker." >&2
  exit 1
fi

TMP=$(mktemp -d "${TMPDIR:-/tmp}/regen-claudemd.XXXXXX") || exit 1
trap 'rm -rf "$TMP"' EXIT

# Print $1 with the body of its first autogen block removed (BEGIN/END kept).
strip_block() {
  awk -v b="$BEGIN_PREFIX" -v e="$END_LINE" '
    !done && !in_block && index($0, b) == 1 { print; in_block = 1; next }
    in_block && $0 == e { print; in_block = 0; done = 1; next }
    !in_block { print }
  ' "$1"
}

# Print only the body of $1's first autogen block.
block_body() {
  awk -v b="$BEGIN_PREFIX" -v e="$END_LINE" '
    !done && !in_block && index($0, b) == 1 { in_block = 1; next }
    in_block && $0 == e { in_block = 0; done = 1; next }
    in_block { print }
  ' "$1"
}

strip_block "$1" > "$TMP/base"
strip_block "$2" > "$TMP/ours"
strip_block "$3" > "$TMP/theirs"
block_body "$2" > "$TMP/body"

# Labels default to the placeholders git would expand (older git passes them
# through literally, which is still more legible than a temp-file name).
git merge-file -p \
  -L "${6:-ours}" -L "${5:-base}" -L "${7:-theirs}" \
  "$TMP/ours" "$TMP/base" "$TMP/theirs" > "$TMP/merged"
STATUS=$?
# merge-file exits with the conflict count (>0), or <0 (≥128 here) on error.
if [ "$STATUS" -ge 128 ]; then
  echo "regen-claudemd merge driver: git merge-file failed on $4 (exit $STATUS)." >&2
  exit "$STATUS"
fi

# Re-insert the current side's autogen body after the first BEGIN anchor.
awk -v b="$BEGIN_PREFIX" -v body="$TMP/body" '
  { print }
  !done && index($0, b) == 1 {
    while ((getline line < body) > 0) print line
    done = 1
  }
' "$TMP/merged" > "$2" || exit 1

mkdir -p "$GITDIR/singularity-merge-markers"
touch "$GITDIR/singularity-merge-markers/generated"
[ "$STATUS" -eq 0 ] || exit 1
exit 0
